        "emotional_tone": "恐惧与困惑",
        "key_scenes": ["林晚偷偷跟踪沈砚", "发现墙上的刻字记录", "翻看病历本发现更多秘密", "沈砚的独白揭示他的内心"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "破碎的镜子",
        "core_event": "林晚质问沈砚真相，沈砚承认一切都是为了让她依赖自己，并说出'只有疯子的爱情才纯粹'。同时她发现医生的实验记录。",
        "emotional_tone": "愤怒与绝望",
        "key_scenes": ["林晚与沈砚的对峙", "沈砚坦白自己的动机", "发现医生的实验笔记", "林晚考虑逃离"]
      }
    ],
    "turning_point": "林晚决定不逃离，而是要面对这场疯狂的爱情"
  },
  "act_three": {
    "description": "林晚选择自愿参与这场病态的爱情游戏，在疯狂中找到救赎",
    "key_chapters": [
